//! 📤️ The neutral transfer matrix preserves original payload pointers and denied source custody.
use super::*;
use semio_framework_value::FromValue;
#[test]fn original_birth_moves_only_after_paid_handoff(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let member_fixture:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let member=crate::LayoutDrawingMember::from_value(semio_framework_value::DslValue::from(member_fixture["cases"][0]["member"].clone())).unwrap();let original=String::from("original Drawing payload");let pointer=original.as_ptr();let birth=LayoutDrawingBirth{source:crate::drawing_member::LayoutDrawingBirthSource::Document,member,initial:original};let mut source=if row["source"].as_bool().unwrap(){Some(birth)}else{None};let mut target=None;let d=drawing_birth_transfer_demand::<String>();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let result=transfer_drawing_birth(&mut source,&mut target,denied,row["cancelled"].as_bool().unwrap()).unwrap();assert!(!result.done);assert!(target.is_none());assert_eq!(source.as_ref().map(|value|value.initial.as_ptr()),if row["source"].as_bool().unwrap(){Some(pointer)}else{None});}if row["destination"].as_bool().unwrap(){target=source.take();assert!(transfer_drawing_birth(&mut source,&mut target,grant,false).is_err());assert_eq!(target.as_ref().unwrap().initial.as_ptr(),pointer);continue}let result=transfer_drawing_birth(&mut source,&mut target,grant,row["cancelled"].as_bool().unwrap());if row["expected"]=="missing"{assert!(result.is_err());continue}let result=result.unwrap();assert_eq!(result.progress.copied_bytes,d.copy_bytes);assert_eq!(result.progress.retained_capacity_bytes,0);assert_eq!(result.progress.released_bytes,0);if row["expected"]=="cancelled"{assert!(source.is_some());assert!(target.is_none());}else{assert!(source.is_none());assert_eq!(target.as_ref().unwrap().initial.as_ptr(),pointer);}}}
